const ttext = (x, y, label, size, fill, attrs = '') => `<text x="${x}" y="${y}" text-anchor="middle" font-family="Times New Roman,Times,serif" font-size="${size}" fill="${fill}" ${attrs}>${label}</text>`;

// Shared house rendering: glass fill, clipped label art, shade overlay, highlights, closure on top.
function bottle({slug, title, outline, glass, label, highlights, closure, defs}) {
  return wrap(slug, title, `${shadow(33)}
<path d="${outline}" fill="${ref(glass)}"/>
<g clip-path="${ref('bodyclip')}">
${label}
<path d="${outline}" fill="${ref('shade')}" opacity=".6"/>
${highlights}
</g>
${closure}`, `<clipPath id="__ID__bodyclip"><path d="${outline}"/></clipPath>
${defs}`);
}

